import { chromium } from "@playwright/test";
import assert from "node:assert/strict";
import { readFileSync, mkdirSync } from "node:fs";
import { randomBytes } from "node:crypto";
import { KyroClient } from "../sdk/kyro.js/dist/index.js";

// Uses only the local accounts generated by bot-live-smoke.mjs. No secrets in output.
const credentials = JSON.parse(readFileSync(".env.bots-browser.local", "utf8"));
assert.match(credentials.url, /^http:\/\/127\.0\.0\.1:/);
const browser = await chromium.launch({ headless: true });
const errors = [];
let activePage;
let bot;
mkdirSync("test-results", { recursive: true });
async function login(email, viewport = { width: 1440, height: 1000 }) {
  const context = await browser.newContext({ viewport });
  // Prevent this test from connecting to an accidentally configured cloud deployment.
  await context.route(/https?:\/\/[^/]+\.convex\.(cloud|site)\//, (route) =>
    route.abort(),
  );
  const page = await context.newPage();
  activePage = page;
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto("http://127.0.0.1:5173/auth");
  await page.locator('input[name="email"]').fill(email);
  await page.locator('input[name="password"]').fill(credentials.password);
  await page.getByRole("button", { name: /^sign in$/i }).click();
  await page.waitForURL(/\/dashboard/, { timeout: 30000 });
  return page;
}
try {
  const owner = await login(credentials.ownerEmail);
  await owner.goto("http://127.0.0.1:5173/dashboard/developers");
  await owner.getByRole("button", { name: "New application" }).click();
  const name = `Browser ${randomBytes(4).toString("hex")}`;
  await owner.getByLabel("Application name", { exact: true }).fill(name);
  await owner
    .getByLabel("Bot username", { exact: true })
    .fill(name.toLowerCase().replace(" ", "_"));
  await owner
    .getByLabel("Description", { exact: true })
    .fill("Browser-tested bot application.");
  await owner
    .getByRole("button", { name: "Create application", exact: true })
    .click();
  await owner.getByRole("heading", { name: "Save your bot token" }).waitFor();
  const token = await owner.locator('[role="dialog"] pre').innerText();
  assert.match(token, /^kyro_bot_[a-f0-9]{64}$/);
  await owner.getByRole("button", { name: "I've saved it" }).click();
  await owner.waitForURL(/\/developers\/[^/]+$/);
  await owner
    .getByRole("button", { name: "Slash Commands", exact: true })
    .click();
  await owner.getByLabel("Command name", { exact: true }).fill("ping");
  await owner
    .getByLabel("Description", { exact: true })
    .fill("Browser ping command");
  await owner
    .getByRole("button", { name: "Save command", exact: true })
    .click();
  await owner.getByText("Browser ping command", { exact: false }).waitFor();
  await owner
    .getByRole("button", { name: "Installation", exact: true })
    .click();
  await owner.getByRole("link", { name: "Install bot", exact: true }).click();
  await owner
    .getByLabel("Server", { exact: true })
    .selectOption(credentials.serverId);
  await owner
    .getByRole("button", { name: "Authorize bot", exact: true })
    .click();
  await owner.waitForURL(/\/dashboard\/s\//);
  bot = new KyroClient({ token, baseUrl: `${credentials.site}/api/bots/v1` });
  bot.on("interactionCreate", (interaction) =>
    interaction
      .reply("Browser private pong", { ephemeral: true })
      .then(() => undefined),
  );
  await bot.login();
  await owner.goto(
    `http://127.0.0.1:5173/dashboard/developers/${credentials.applicationId}`,
  );
  await owner
    .getByRole("button", { name: "Webhooks & Events", exact: true })
    .click();
  await owner.screenshot({ path: "test-results/bot-developer-desktop.png" });
  await owner.setViewportSize({ width: 390, height: 844 });
  assert(
    await owner.evaluate(
      () => document.documentElement.scrollWidth <= innerWidth,
    ),
    "Mobile developer portal must fit the viewport",
  );
  await owner.screenshot({ path: "test-results/bot-developer-mobile.png" });
  const member = await login(credentials.otherEmail, {
    width: 390,
    height: 844,
  });
  await member.goto(
    `http://127.0.0.1:5173/dashboard/bots/${credentials.applicationId}`,
  );
  await member
    .getByRole("link", { name: "Add to server", exact: true })
    .waitFor();
  await member.screenshot({ path: "test-results/bot-profile-mobile.png" });
  assert(
    await member.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth,
    ),
    "Mobile profile must not overflow horizontally",
  );
  await member.goto(
    `http://127.0.0.1:5173/dashboard/s/${credentials.serverId}/c/${credentials.channelId}`,
  );
  await member
    .locator("textarea")
    .fill(`/${name.toLowerCase().replace(" ", "_")}:ping`);
  await member.locator("textarea").press("Enter");
  await member
    .getByRole("button", { name: "Run command", exact: true })
    .click();
  await member.getByText("Browser private pong", { exact: true }).waitFor();
  await owner.goto(
    `http://127.0.0.1:5173/dashboard/s/${credentials.serverId}/c/${credentials.channelId}`,
  );
  await owner.locator("textarea").waitFor();
  assert.equal(
    await owner.getByText("Browser private pong", { exact: true }).count(),
    0,
  );
  assert.equal(errors.length, 0, errors.join("\n"));
  console.log(
    "PASS: browser password sign-in, portal creation/token display, command registration, installation consent, desktop settings, mobile profile and private response rendering.",
  );
} catch (error) {
  if (activePage) {
    await activePage.screenshot({
      path: "test-results/bot-browser-failure.png",
    });
    console.error("Page:", activePage.url());
    console.error(
      (await activePage.locator("body").innerText())
        .replace(/kyro_bot_[a-f0-9]{64}/g, "[redacted]")
        .slice(-3000),
    );
  }
  throw error;
} finally {
  await bot?.destroy();
  await browser.close();
}
